insert into public.teachers (id, slug, name, initial, subject, grade, city, years, headline, bio, education, live_schedule, price_month, price_term, color, badge, verified, rating, review_count, student_count) values ('00000000-0000-4000-8000-000000000001', 'khaled-omari', 'خالد العمري', 'خ', 'رياضيات', 'توجيهي علمي', 'عمّان', 14, 'رياضيات التوجيهي العلمي من الأساس للعلامة الكاملة، بشرح مرتّب وحلّ أوراق وزارية.', 'بدرّس رياضيات التوجيهي من 14 سنة بمدارس عمّان ومراكزها. بقسّم كل وحدة لدروس قصيرة، وبعد كل درس في ورقة عمل واختبار قصير بيصحّح لحاله، وكل أسبوعين حصة مباشرة لحل أسئلة الطلاب والأوراق الوزارية.', 'ماجستير رياضيات تطبيقية، الجامعة الأردنية', 'السبت والثلاثاء · 7:00 مساءً', 25, 65, '#0f4c45', 'الأكثر اشتراكًا', true, 4.9, 312, 1240);
